      ctx.textAlign = "right";
      let rawLabel = entry.sublabel ? `[${entry.sublabel}] ${entry.tag}` : entry.tag;
      if (rawLabel.length > 42)
        rawLabel = rawLabel.slice(0, 40) + "...";
      ctx.fillText(rawLabel, plotX - 10, y + BAR_HEIGHT / 2 + 4);
      ctx.fillStyle = singleColor;
