var DashboardView = class extends import_obsidian12.ItemView {
  constructor(leaf, tagIndex, audienceIndex, engagementStore) {
    super(leaf);
    this.activeTab = "strategy";
    this.contentArea = null;
    this.tagIndex = tagIndex;
    this.audienceIndex = audienceIndex;
    this.engagementStore = engagementStore;
  }
  getViewType() {
    return VIEW_TYPE_CONTENT_COMPASS;
  }
  getDisplayText() {
    return "Content Compass";
  }
  getIcon() {
    return "compass";
  }
  // Nhóm 3: Vòng đời nạp giao diện Dashboard
  async onOpen() {
    const container = this.containerEl.children[1];
    container.empty();
    container.addClass("content-compass-container");
    const tabBar = container.createDiv({ cls: "content-compass-tab-bar" });
    const tabs = [
      { id: "strategy", icon: "compass", label: "Strategy" },
      { id: "analytics", icon: "bar-chart-2", label: "Analytics" },
      { id: "advisor", icon: "sparkles", label: "Advisor" }
    ];
    const tabsGroup = tabBar.createDiv({ cls: "content-compass-tabs-group" });
    this.contentArea = container.createDiv({ cls: "content-compass-tab-content" });
    for (const tab of tabs) {
      const btn = tabsGroup.createEl("button", {
        cls: `content-compass-tab-btn ${this.activeTab === tab.id ? "is-active" : ""}`
      });
      setIconLabel(btn, tab.icon, tab.label);
      btn.addEventListener("click", () => {
        this.activeTab = tab.id;
        tabsGroup.querySelectorAll(".content-compass-tab-btn").forEach((el) => {
          el.removeClass("is-active");
        });
        btn.addClass("is-active");
        if (this.contentArea) {
          this.renderTabContent(this.contentArea);
        }
      });
    }
    const actionsGroup = tabBar.createDiv({ cls: "content-compass-tab-actions" });
    const refreshBtn = actionsGroup.createEl("button", {
      cls: "content-compass-refresh-btn"
    });
    setIconLabel(refreshBtn, "refresh-cw", "L\xE0m m\u1EDBi");
    refreshBtn.setAttribute("title", "T\u1EA3i l\u1EA1i d\u1EEF li\u1EC7u Audience v\xE0 Topic t\u1EEB Vault");
    refreshBtn.addEventListener("click", async () => {
      setIconLabel(refreshBtn, "loader", "\u0110ang t\u1EA3i...", true);
      await this.audienceIndex.initialize();
      await this.tagIndex.initialize();
      await this.engagementStore.initialize();
      this.refresh();
      setIconLabel(refreshBtn, "refresh-cw", "L\xE0m m\u1EDBi");
    });
    this.renderTabContent(this.contentArea);
  }
  // Nhóm 4: Phương thức làm mới giao diện tức thời
  refresh() {
    if (this.contentArea) {
      this.renderTabContent(this.contentArea);
    }
  }
  // Nhóm 5: Render nội dung theo Tab đang chọn
  renderTabContent(contentEl) {
    contentEl.empty();
    if (this.activeTab === "strategy") {
      const strategyLayout = contentEl.createDiv({ cls: "content-compass-strategy-layout" });
      const topSection = strategyLayout.createDiv({ cls: "content-compass-top-section" });
      const pillarMapView = new PillarMapView(topSection, this.tagIndex, this.audienceIndex, this.app, this.engagementStore);
      pillarMapView.render();
      const bottomSection = strategyLayout.createDiv({ cls: "content-compass-bottom-section" });
      const hierarchyView = new HierarchyBrowserView(bottomSection, this.audienceIndex, this.app);
      hierarchyView.render();
      const healthView = new PillarHealthView(bottomSection, this.tagIndex, this.audienceIndex);
      healthView.render();
    } else if (this.activeTab === "analytics") {
      const analyticsLayout = contentEl.createDiv({ cls: "content-compass-analytics-layout" });
      const importSection = analyticsLayout.createDiv({ cls: "content-compass-analytics-import" });
      const importView = new ImportEngineView(
        importSection,
        this.engagementStore,
        this.app,
        () => this.refresh()
      );
      importView.render();
      const timelineSection = analyticsLayout.createDiv({ cls: "content-compass-analytics-chart" });
      const timelineView = new TimelineChartView(
        timelineSection,
        this.engagementStore,
        this.audienceIndex,
        (post) => {
          void importView.focusAndHighlightPost(post);
        }
      );
      timelineView.render();
      const rankingSection = analyticsLayout.createDiv({ cls: "content-compass-analytics-chart" });
      const rankingView = new TagRankingView(rankingSection, this.engagementStore, this.audienceIndex);
      rankingView.render();
    } else if (this.activeTab === "advisor") {
      const placeholder = contentEl.createDiv({ cls: "content-compass-placeholder" });
      setIconLabel(
        placeholder,
        "sparkles",
        "Module Advisor: S\u1EBD \u0111\u01B0\u1EE3c k\xEDch ho\u1EA1t t\u1EA1i Phase 3 (\u0110\u1EC1 xu\u1EA5t \xFD t\u01B0\u1EDFng & ch\u1EE7 \u0111\u1EC1 theo tr\u1ECDng s\u1ED1 Buyer Job)."
      );
    }
  }
  async onClose() {
    this.contentArea = null;
  }
};

// src/main.ts
var ContentCompassPlugin = class extends import_obsidian13.Plugin {
  constructor() {
    super(...arguments);
    this.audienceIndex = null;
    this.tagIndex = null;
    this.engagementStore = null;
    this.pipelineWatcher = null;
    this.watcherDebounce = null;
  }
  // Nhóm 2: Vòng đời khởi chạy Plugin (onload)
  async onload() {
    console.log("[Content Compass] Kh\u1EDFi ch\u1EA1y plugin...");
    this.audienceIndex = new AudienceIndex(this.app);
    this.tagIndex = new TagIndex(this.app);
    this.engagementStore = new EngagementStore(this.app, this.tagIndex);
    this.registerView(
      VIEW_TYPE_CONTENT_COMPASS,
      (leaf) => new DashboardView(leaf, this.tagIndex, this.audienceIndex, this.engagementStore)
    );
    this.addRibbonIcon("compass", "Content Compass", () => {
      this.activateView();
    });
    this.addCommand({
      id: "open-content-compass",
      name: "M\u1EDF Content Compass Dashboard",
      callback: () => {
        this.activateView();
      }
    });
    this.app.workspace.onLayoutReady(async () => {
      if (this.audienceIndex) {
        await this.audienceIndex.initialize();
      }
      if (this.tagIndex) {
        await this.tagIndex.initialize();
      }
      if (this.engagementStore) {
        await this.engagementStore.initialize();
      }
      console.log("[Content Compass] Du lieu AudienceIndex, TagIndex & EngagementStore da san sang.");
      this.refreshOpenViews();
      this.setupPipelineDirectoryWatcher();
      window.setTimeout(() => this.runDueFacebookTracker(), 1e4);
    });
    this.registerInterval(
      window.setInterval(() => {
        this.runDueFacebookTracker();
      }, 5 * 60 * 1e3)
    );
    this.registerEvent(
      this.app.metadataCache.on("changed", async (file) => {
        const normPath = file.path.replace(/\\/g, "/");
        if (normPath.startsWith("01-Atomic/Audiences/")) {
          if (this.audienceIndex) {
            await this.audienceIndex.initialize();
            this.refreshOpenViews();
          }
        } else if (normPath.startsWith("03-Content/")) {
          if (this.engagementStore) {
            await this.engagementStore.initialize();
            this.refreshOpenViews();
          }
        }
      })
    );
    this.registerEvent(
      this.app.vault.on("delete", async (file) => {
        const normPath = file.path.replace(/\\/g, "/");
        if (normPath.startsWith("01-Atomic/Audiences/")) {
          if (this.audienceIndex) {
            await this.audienceIndex.initialize();
            this.refreshOpenViews();
          }
        }
      })
    );
  }
  // Theo doi thu muc an .content-pipeline bang fs.watch (vi Obsidian vault.on bo qua dot-folder)
  setupPipelineDirectoryWatcher() {
    try {
      const fs = require("fs");
      const path = require("path");
      const adapter = this.app.vault.adapter;
      const basePath = adapter == null ? void 0 : adapter.basePath;
      if (!basePath)
        return;
      const pipelineDir = path.join(basePath, ".content-pipeline");
      if (!fs.existsSync(pipelineDir)) {
        fs.mkdirSync(pipelineDir, { recursive: true });
      }
      this.pipelineWatcher = fs.watch(pipelineDir, { recursive: true }, (_eventType, filename) => {
        if (!filename)
          return;
        const norm = filename.replace(/\\/g, "/");
        if (norm.startsWith("engagement/") && norm.endsWith(".json")) {
          if (this.watcherDebounce)
            window.clearTimeout(this.watcherDebounce);
          this.watcherDebounce = window.setTimeout(async () => {
            if (this.engagementStore) {
              await this.engagementStore.initialize();
              this.refreshOpenViews();
            }
          }, 600);
        }
      });
    } catch (e) {
      console.warn("[Content Compass] Kh\xF4ng th\u1EC3 kh\u1EDFi t\u1EA1o fs.watch cho .content-pipeline:", e);
    }
  }
  // Kich hoat script Python quet ngam cac bai viet/Fanpage da den han
  runDueFacebookTracker() {
    try {
      const { spawn } = require("child_process");
      const path = require("path");
      const adapter = this.app.vault.adapter;
      const vaultPath = adapter == null ? void 0 : adapter.basePath;
      if (!vaultPath)
        return;
      const pyExe = resolvePythonExe();
      const scriptPath = path.resolve(vaultPath, "..", ".agents", "scripts", "facebook_realtime_tracker.py");
      spawn(pyExe, [scriptPath, "--vault", vaultPath, "--run-due"], {
        windowsHide: true,
        stdio: "ignore"
      });
    } catch (e) {
    }
  }
  // Nhóm 3: Kích hoạt và mở Dashboard Tab trên Workspace
  async activateView() {
    const { workspace } = this.app;
    let leaf = null;
    const leaves = workspace.getLeavesOfType(VIEW_TYPE_CONTENT_COMPASS);
    if (leaves.length > 0) {
      leaf = leaves[0];
    } else {
      const rightLeaf = workspace.getLeaf(true);
      if (rightLeaf) {
        leaf = rightLeaf;
        await leaf.setViewState({
          type: VIEW_TYPE_CONTENT_COMPASS,
          active: true
        });
      }
    }
    if (leaf) {
      workspace.revealLeaf(leaf);
    }
  }
  // Nhóm 4: Cập nhật lại giao diện trên toàn bộ các tab Dashboard đang mở
  refreshOpenViews() {
    const leaves = this.app.workspace.getLeavesOfType(VIEW_TYPE_CONTENT_COMPASS);
    for (const leaf of leaves) {
      if (leaf.view instanceof DashboardView) {
        leaf.view.refresh();
      }
    }
  }
  // Nhóm 5: Dọn dẹp tài nguyên khi tắt Plugin (onunload)
  onunload() {
    if (this.watcherDebounce) {
      window.clearTimeout(this.watcherDebounce);
      this.watcherDebounce = null;
    }
    if (this.pipelineWatcher) {
      try {
        this.pipelineWatcher.close();
      } catch (e) {
      }
      this.pipelineWatcher = null;
    }
    console.log("[Content Compass] D\u1EE1 b\u1ECF plugin th\xE0nh c\xF4ng.");
  }
};
